import{_ as t,o,c as d,a2 as n}from"./chunks/framework.7w-lhQN6.js";const p=JSON.parse('{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"reference/configuration.md","filePath":"reference/configuration.md","lastUpdated":1793550481000}'),a={name:"reference/configuration.md"};function s(c,e,r,i,l,h){return o(),d("div",null,[...e[0]||(e[0]=[n('<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h1><p>This page lists where MCP Lens stores its data and every VS Code extension setting, so you can look up a key or a path without digging through the walkthrough. For what to change and why, see <a href="/MCPLens/guide/vscode-extension">the VS Code extension guide</a> and <a href="/MCPLens/guide/global-actions">Global Actions</a>.</p><h2 id="data-locations" tabindex="-1">Data locations <a class="header-anchor" href="#data-locations" aria-label="Permalink to &quot;Data locations&quot;">​</a></h2><p>Everything MCP Lens keeps lives under <code>~/.mcplens</code>. It is never written into your project or into a client&#39;s own config or logs.</p><table tabindex="0"><thead><tr><th>Path</th><th>Contents</th></tr></thead><tbody><tr><td><code>~/.mcplens/lens.db</code></td><td>The SQLite database: scanned tool definitions, hook-observed calls, and sessions.</td></tr><tr><td><code>~/.mcplens/inbox</code></td><td>Hook events queued before the extension or CLI moves them into the database.</td></tr><tr><td><code>~/.mcplens/db-writer.lock</code></td><td>The writer lease file that keeps the extension and the CLI from writing at the same time.</td></tr><tr><td><code>~/.mcplens/oauth</code></td><td>OAuth tokens and client registrations for authenticated MCP servers, written with owner-only file permissions.</td></tr></tbody></table><h2 id="extension-settings" tabindex="-1">Extension settings <a class="header-anchor" href="#extension-settings" aria-label="Permalink to &quot;Extension settings&quot;">​</a></h2><p>Open these from VS Code&#39;s Settings UI by searching <code>MCP Lens</code>, or edit <code>settings.json</code> directly.</p><table tabindex="0"><thead><tr><th>Setting</th><th>Type</th><th>Default</th><th>Meaning</th></tr></thead><tbody><tr><td><code>mcpLens.reportDays</code></td><td>number</td><td><code>30</code></td><td>Days the status bar summary and reports aggregate over.</td></tr><tr><td><code>mcpLens.reportDetail</code></td><td><code>summary</code> | <code>full</code></td><td><code>summary</code></td><td>Detail level for the <strong>MCP Lens: Show Report</strong> command. <code>summary</code> caps candidate and normal tool lists at 5; items needing action or inspection always show in full either way.</td></tr><tr><td><code>mcpLens.autoScan</code></td><td><code>prompt</code> | <code>always</code> | <code>never</code></td><td><code>never</code></td><td>Automatic scanning when a new server is detected. <code>prompt</code> asks first, <code>always</code> scans right away (after your first manual scan from the walkthrough), <code>never</code> scans only when you trigger it.</td></tr><tr><td><code>mcpLens.authIgnore</code></td><td>string[]</td><td><code>[]</code></td><td>Server names to stop nagging about sign-in for. Populated automatically by the &quot;Don&#39;t ask for this server&quot; button.</td></tr><tr><td><code>mcpLens.oauthClients</code></td><td>object</td><td><code>{}</code></td><td>OAuth client ids for servers that reject automatic client registration, e.g. <code>{ &quot;github&quot;: &quot;Iv1.abc123&quot; }</code>. Client secrets are never stored here; they go to <code>~/.mcplens/oauth/clients.json</code>.</td></tr><tr><td><code>mcpLens.unsupportedServers</code></td><td>string[]</td><td><code>[]</code></td><td>Server names Lens determined it cannot support (for example, servers that reject automatic client registration). Populated automatically; these are hidden from the tree and never prompted again.</td></tr><tr><td><code>mcpLens.inferenceProvider</code></td><td><code>auto</code> | <code>claude</code> | <code>codex</code></td><td><code>auto</code></td><td>Provider used for dependency analysis. <code>auto</code> picks Claude when both CLIs are installed; set this to pin one explicitly.</td></tr><tr><td><code>mcpLens.autoAnalyze</code></td><td>boolean</td><td><code>false</code></td><td>After an automatic scan, analyze new tools with the provider CLI to judge whether each can be turned off independently. This spends the provider&#39;s tokens and sends it tool definitions and usage counts. It never runs before you have consented once from the walkthrough.</td></tr><tr><td><code>mcpLens.claudeModel</code></td><td>string</td><td><code>haiku</code></td><td>Claude model used for dependency analysis.</td></tr><tr><td><code>mcpLens.codexModel</code></td><td>string</td><td><code>gpt-5.6-luna</code></td><td>Codex model used for dependency analysis.</td></tr><tr><td><code>mcplens.dependencyAnalysis.rollout</code></td><td><code>off</code> | <code>claude</code> | <code>codex</code> | <code>all</code></td><td><code>off</code></td><td>Which client is allowed to use global actions (disabling an unused tool by editing that client&#39;s config file). Analysis, cache, and details stay available at every value, including <code>off</code>. Gemini CLI is never allowed here; global actions do not support it.</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><code>mcplens.dependencyAnalysis.rollout</code> uses a different (lowercase) settings namespace than every other key on this page. That is not a typo, it is the exact key VS Code reads; double-check the casing if you set it by hand in <code>settings.json</code>.</p></div>',9)])])}const g=t(a,[["render",s]]);export{p as __pageData,g as default};
